/// <summary>
///    Finds the specified record in the <c>KCS_KBVRelationsToBV</c> table.
/// </summary>
/// <param name="_KCS_KBVRelationID">
///    First record ID of the <c>KCS_KBVRelationsToBV</c> record to find.
/// </param>
/// <param name="_KCS_KBVBuildingProjectID">
///    Second record ID of the <c>KCS_KBVRelationsToBV</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>KCS_KBVRelationsToBV</c> table; otherwise, an empty record.
/// </returns>
public static KCS_KBVRelationsToBV find(KCS_KBVRelationID           _KCS_KBVRelationID,
                                        KCS_KBVBuildingProjectID    _KCS_KBVBuildingProjectID,
                                        boolean                     _forUpdate = false)
{
    KCS_KBVRelationsToBV record;

    record.selectForUpdate(_forUpdate);

    if(_KCS_KBVRelationID && _KCS_KBVBuildingProjectID)
    {
        select firstonly record
        index hint KCS_KBVRelationsToBVIdx
        where   record.KCS_KBVRelationID        == _KCS_KBVRelationID
            &&  record.KCS_KBVBuildingProjectID == _KCS_KBVBuildingProjectID;
    }

    return record;
}

