/// <summary>
///    AVA <c>editContactPersonName</c> method.
/// </summary>
/// <param name="_set">
///    <c>boolean</c> as type
/// </param>
/// <param name="_name">
///    <c>ContactPersonName</c> as type
/// </param>
/// <returns>
///     <c>ContactPersonName</c> as type
/// </returns>
edit ContactPersonName  editContactPersonName(boolean _set, ContactPersonName _name)
{
    // ToDo: ContactPerson name and validation against customer not yet implemented as in 2009
    ContactPersonName                   retVal;

    AVAKBVDirPartyContactPersonHelper   locAVAKBVDirPartyContactPersonHelper;

    if(_set)
    {
        locAVAKBVDirPartyContactPersonHelper = new AVAKBVDirPartyContactPersonHelper();

        locAVAKBVDirPartyContactPersonHelper.parmSet(_set);
        locAVAKBVDirPartyContactPersonHelper.parmDataAreaId(curExt());
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyId(this.DirPartyId);
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyName('');
        //locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(this.ContactPersonId);
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(_name);
        //locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(_name);
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(ContactPerson::find(_name).personName());

        retVal = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonName();

        this.ContactPersonId = locAVAKBVDirPartyContactPersonHelper.parmContactPersonId();
        this.ContactPersonParty = ContactPerson::find(this.ContactPersonId).Party;

        if(locAVAKBVDirPartyContactPersonHelper.parmRefresh())
        {
            if (FormDataUtil::getFormDataSource(this))
            {
                FormDataUtil::getFormDataSource(this).refresh();
            }
        }
    }

    return retVal;
}

/// <summary>
///    AVA <c>contactPerson</c> method.
/// </summary>
/// <param name="_forUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>ContactPerson</c> as type
/// </returns>
ContactPerson contactPerson(boolean _forUpdate = false)
{
    if (this.ContactPersonId)
    {
        return ContactPerson::find(this.ContactPersonId, _forUpdate);
    }
    else
    {
        return ContactPerson::findByPartyRecId(this.ContactPersonParty, _forUpdate);
    }
}

/// <summary>
///    AVA <c>checkContactPerson</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as type
/// </returns>
boolean checkContactPerson()
{
    ContactPerson   contactPerson;
    CustAccount     locCustAccount;

    locCustAccount  = contactPerson.getCustAccount(); // ToDo: just to get positive check maybe from the related quotation

    contactPerson = this.contactPerson();

    //ToDo:  Check BP related customer if needed
    if (contactPerson.getCustAccount() != locCustAccount)
    {
        return false;
    }
    return true;
}

/// <summary>
///    AVA <c>createSmmBusRelTableForCompany</c> method.
/// </summary>
/// <param name="_dirPartyRecId">
///    <c>DirPartyRecId</c> as type
/// </param>
public static void createSmmBusRelTableForCompany(DirPartyRecId _dirPartyRecId)
{
    smmBusRelTable           locsmmBusRelTable;
    ContactPerson            contactPerson;
    LogisticsPostalAddress   address = DirParty::primaryPostalAddress(_dirPartyRecId);
    CompanyInfo              companyInfo;
    smmBusRelTable           companyBusRelTable;

    List                     companyContactList = new List(Types::Record);
    ListIterator             companyContactListIterator;

    while select companyInfo
        where companyInfo.DataArea != 'DAT'
    {
        changecompany(companyInfo.DataArea)
        {
            ContactPerson            companyContactPerson;
            companyBusRelTable = smmBusRelTable::findByParty(_dirPartyRecId);
            if (companyBusRelTable.RecId)
            {
                while select companyContactPerson
                    where companyContactPerson.ContactForParty == _dirPartyRecId
                {
                    companyContactList.addEnd(companyContactPerson);
                }
                break;
            }
        }
    }

    locsmmBusRelTable.initValue();
    locsmmBusRelTable.initFromDirParty(DirParty::constructFromPartyRecId(_dirPartyRecId));
    locsmmBusRelTable.BusRelAccount = smmParameters::getNumber(smmNumbSeqUsed::BusRel);
    locsmmBusRelTable.Party         = _dirPartyRecId;
    locsmmBusRelTable.NDX_initSalesGroupAndDistrictFromAddr(address.ZipCode, address.CountryRegionId, locsmmBusRelTable.dataAreaId);
    if (companyBusRelTable)
    {
        locsmmBusRelTable.copyFromSmmBusRelTable(companyBusRelTable);
    }
    locsmmBusRelTable.insert();

    ContactPerson            companyContactPerson;
    companyContactListIterator = new ListIterator(companyContactList);
    while (companyContactListIterator.more())
    {
        companyContactPerson = companyContactListIterator.value();
        contactPerson.clear();
        contactPerson.initValue();
        contactPerson.initFromBusRel(companyBusRelTable);
        contactPerson.copyFromCompanyContactPerson(companyContactPerson);
        contactPerson.ContactPersonId  = NumberSeq::newGetNum(ContactPerson::numRefContactPersonId()).num();
        contactPerson.insert();
        companyContactListIterator.next();
    }
}

/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(KCS_KBVRelationsToBV,DirPartyId) :
            smmBusRelTable      checkSmmBusRelTable;
            checkSmmBusRelTable = smmBusRelTable::findByParty(this.DirPartyId);
            if (!checkSmmBusRelTable.RecId && this.DirPartyId)
            {
                KCS_KBVRelationsToBV::createSmmBusRelTableForCompany(this.DirPartyId);
            }
            break;

        default : 
            break;
    }
}
